nta.declaration:
/*** MAP BOUNDARIES & CONSTANTS ***/
const int MAX_X = 17;         // Rightmost boundary
const int MAX_Y = 12;         // Upmost boundary (home bays)
const int INITIAL_X = 9;      // Initial x coordinate (could be theoretically set to any valid value)
const int INITIAL_Y = 0;      // Initial y coordinate (could be theoretically set to any empty row)
const int WRAP_SIZE = 2;      // Space outside the map where objects wrap (Pac-Man logic)

/*** TIMERS (1 time unit = 0.1s) ***/
const int INITIAL_TIMEOUT = 300;     // 30s game timer
const int RESPAWN_DELAY = 20;        // 2s initial delay    
const int MOVE_DELAY = 1;            // 1 time unit inter-move delay to prevent Zeno behaviour
const int MAX_OBJECT_SPEED = 10;     // Maximum speed for any object
const int EMERGED_TIME = 100;        // 10s emerged time for diving turtles
const int SUBMERGING_TIME = 50;      // 5s submerging time for diving turtles
const int SUBMERGED_TIME = 100;      // 10s submerged time for diving turtles
const int EMERGING_TIME = 50;        // 5s emerging time for diving turtles
const int TOTAL_DIVE_CYCLE = EMERGED_TIME + SUBMERGING_TIME + SUBMERGED_TIME + EMERGING_TIME;

/*** SCORING ***/
const int MOVE_SCORE = 1;
const int BAY_FILLED_SCORE = 5;
const int LEVEL_WON_SCORE = 100;
const int LIVES = 4; // 4 respawns means 5 lives (0 to 4)

/*** FROGGER VARIABLES ***/

// Frogger coordinates
int[0, MAX_X + WRAP_SIZE] frog_x = INITIAL_X;
int[0, MAX_Y] frog_y = INITIAL_Y;

// Lives, score and home bays
int[0, LIVES] lives = LIVES;
int score = 0;
int[0, 5] home_bays_filled = 0;
bool bay_occupied[5] = {false, false, false, false, false};

/*** CHANNELS ***/
urgent broadcast chan die; // Sender: GameEngine -- Receiver: Frogger

/*** CONFIGURATION BLUEPRINTS ***/

// Generic moving entity configuration (vehicle/log/turtle)
typedef struct {
    int size;
    int speed;
    bool is_diving;
} EntityConfig;

// Types of vehicles (can be theoretically initialized with different values, as long as speed <= MAX_OBJECT_SPEED)
const EntityConfig ORANGE  = {1, 3, false};
const EntityConfig DOZER   = {1, 10, false};
const EntityConfig GREEN   = {1, 5, false};
const EntityConfig PURPLE  = {1, 4, false};
const EntityConfig TRUCK   = {2, 7, false};

// Types of floatings (can be theoretically initialized with different values, as long as speed <= MAX_OBJECT_SPEED)
const EntityConfig LOG_S   = {3, 2, false};
const EntityConfig LOG_M   = {9, 7, false};
const EntityConfig LOG_L   = {5, 2, false};
const EntityConfig DIVT_3  = {5, 6, true};  // 3 diving turtles (total 5 spaces)
const EntityConfig DIVT_2  = {3, 2, true};  // 2 diving turtles (total 3 spaces)
const EntityConfig TURT_3  = {5, 6, false}; // 3 turtles (total 5 spaces)
const EntityConfig TURT_2  = {3, 2, false}; // 2 turtles (total 5 spaces)

/*** ACTIVE ENTITIES ***/

// Entity
typedef struct {
    int[0, MAX_X + WRAP_SIZE] x;
    int[0, MAX_Y] y;
    int[0, MAX_OBJECT_SPEED] move_timer;
    int[0, TOTAL_DIVE_CYCLE] dive_timer;
    bool submerged;
    EntityConfig type; 
} ActiveEntity;

// Number of vehicles and floats (can be edited as long as enough vehicles and floats are then used)
const int NUM_VEHICLES = 12;
const int NUM_FLOATS = 10;

ActiveEntity vehicles[NUM_VEHICLES] = {
    {4, 1, 0, 0, false, ORANGE}, {14, 1, 0, 0, false, ORANGE},     
    {2, 2, 0, 0, false, DOZER}, {11, 2, 0, 0, false, DOZER},       
    {4, 3, 0, 0, false, GREEN}, {8, 3, 0, 0, false, GREEN}, {13, 3, 0, 0, false, GREEN}, {17, 3, 0, 0, false, GREEN}, 
    {2, 4, 0, 0, false, PURPLE}, {10, 4, 0, 0, false, PURPLE},     
    {4, 5, 0, 0, false, TRUCK}, {15, 5, 0, 0, false, TRUCK}        
};

ActiveEntity floats[NUM_FLOATS] = {
    {5, 7, 0, 0, false, TURT_3}, {13, 7, 0, 0, false, DIVT_3},                             
    {7, 8, 0, 0, false, LOG_S}, {11, 8, 0, 0, false, LOG_S}, {15, 8, 0, 0, false, LOG_S},    
    {3, 9, 0, 0, false, LOG_M},                                                        
    {2, 10, 0, 0, false, TURT_2}, {10, 10, 0, 0, false, DIVT_2},                        
    {1, 11, 0, 0, false, LOG_L}, {1, 11, 0, 0, false, LOG_L}                            
};

/*** GAME LOGIC FUNCTIONS ***/

/**
 * @brief Evaluates if a vehicle occupies a specific coordinate on the map.
 *        Uses parameterized modulo arithmetic to safely evaluate wrapped coordinates 
 *        on the Torus ring, supporting vehicles of any size across the map boundaries.
 * @param x The x-coordinate to evaluate.
 * @param y The y-coordinate to evaluate.
 * @return true if a vehicle occupies the cell, false otherwise.
 */
bool vehicle_at(int x, int y) {
    int i;
    for (i = 0; i < NUM_VEHICLES; i++) {
        if (vehicles[i].y == y) {
            int dist = (x - vehicles[i].x + (MAX_X + WRAP_SIZE + 1)) % (MAX_X + WRAP_SIZE + 1);
            if (dist < vehicles[i].type.size) return true;
        }
    }
    return false;
}

/**
 * @brief Evaluates if a valid, non-submerged floating platform exists at a specific coordinate.
 *        Uses parameterized modulo arithmetic to safely evaluate wrapped coordinates on the Torus ring.
 * @param x The x-coordinate to evaluate.
 * @param y The y-coordinate to evaluate.
 * @return true if a safe platform occupies the cell, false otherwise.
 */
bool platform_at(int x, int y) {
    int i;
    for (i = 0; i < NUM_FLOATS; i++) {
        if (!floats[i].submerged && floats[i].y == y) {
            int dist = (x - floats[i].x + (MAX_X + WRAP_SIZE + 1)) % (MAX_X + WRAP_SIZE + 1);
            if (dist < floats[i].type.size) return true;
        }
    }
    return false;
}

/**
 * @brief Determines if Frogger's current y-coordinate places him inside the river zone.
 * @param None
 * @return true if Frogger is in the river, false otherwise.
 */
bool is_in_river() {
    return (frog_y >= 7 && frog_y <= MAX_Y - 1);
}

/**
 * @brief Comprehensive safety check. Determines if Frogger's exact position triggers a death condition
 *        (hit by vehicle, drowning in river without a platform, or smashing into the wall between bays).
 * @param None
 * @return true if the current position is lethal, false if safe.
 */
bool is_deadly() {
    if (vehicle_at(frog_x, frog_y)) return true;
    if (is_in_river() && !platform_at(frog_x, frog_y)) return true;
    if (frog_y == MAX_Y && (frog_x % 4 >= 2)) return true;
    return false;
}

/*** VERIFICATION PARAMS FOR QUERY II ***/
// Note: changing initial configuration needs these arrays edited, otherwise Query II fails
const int start_v_y[NUM_VEHICLES] = {1, 1, 2, 2, 3, 3, 3, 3, 4, 4, 5, 5};
const int start_f_y[NUM_FLOATS]   = {7, 7, 8, 8, 8, 9, 10, 10, 11, 11};

template.declaration:
clock t;

/**
 * @brief Centralized game engine tick. Updates all vehicles and floats based on their 
 *        individual speed timers. Handles continuous movement, torus wrapping for 
 *        entities and Frogger, and dive timer progression for turtles.
 * @param None
 * @return void
 */
void update_game() {
    int i;

    // VEHICLE MOVEMENT
    for (i = 0; i < NUM_VEHICLES; i++) {
        vehicles[i].move_timer++;
        if (vehicles[i].move_timer >= vehicles[i].type.speed) {

            if (vehicles[i].y % 2 != 0) {   // Right to Left
                if (vehicles[i].x == 0) vehicles[i].x = MAX_X + WRAP_SIZE;   // Pac-Man logic
                else vehicles[i].x--;
            } else {  // Left to Right
                if (vehicles[i].x == MAX_X + WRAP_SIZE) vehicles[i].x = 0;   // Pac-Man logic
                else vehicles[i].x++;
            }

            vehicles[i].move_timer = 0; // Reset movement timer
        }
    }

    // FLOATINGS MOVEMENT
    for (i = 0; i < NUM_FLOATS; i++) {
        floats[i].move_timer++;

        // MOVEMENT & CARRYING FROGGER
        if (floats[i].move_timer >= floats[i].type.speed) {
            int dist = (frog_x - floats[i].x + (MAX_X + WRAP_SIZE + 1)) % (MAX_X + WRAP_SIZE + 1);
            bool carrying = (frog_y == floats[i].y && dist < floats[i].type.size);

            if (floats[i].y == 8 || floats[i].y == 9 || floats[i].y == 11) {   // Left to Right
                // Move Log
                if (floats[i].x == MAX_X + WRAP_SIZE) floats[i].x = 0;   // Pac-Man logic
                else floats[i].x++;

                // Move Frogger
                if (carrying) {
                    if (frog_x == MAX_X + WRAP_SIZE) frog_x = 0;         // Pac-Man logic
                    else frog_x++;
                }
            } else { // Right to Left
                // Move Log
                if (floats[i].x == 0) floats[i].x = MAX_X + WRAP_SIZE;   // Pac-Man logic
                else floats[i].x--;

                // Move Frogger
                if (carrying) {
                    if (frog_x == 0) frog_x = MAX_X + WRAP_SIZE;         // Pac-Man logic
                    else frog_x--;
                }
            }
            floats[i].move_timer = 0; // Reset movement timer
        }

        // DIVING LOGIC
        if (floats[i].type.is_diving) {
            floats[i].dive_timer++;
            floats[i].submerged = (floats[i].dive_timer > (SUBMERGING_TIME + EMERGED_TIME) && floats[i].dive_timer < TOTAL_DIVE_CYCLE);
            if (floats[i].dive_timer >= TOTAL_DIVE_CYCLE) floats[i].dive_timer = 0;   // Reset dive cycle
        }
    }
}

clock game_timer;            
clock move_timer;    

/**
 * @brief Resets Frogger to his starting coordinates at the bottom center of the map.
 *        Called upon initialization and after losing a life or scoring.
 * @param None
 * @return void
 */
void reposition() {
    frog_x = INITIAL_X;
    frog_y = INITIAL_Y;
}

/**
 * @brief Checks if Frogger is currently positioned safely inside an empty home bay.
 * @param None
 * @return true if Frogger occupies a home bay cell, false otherwise.
 */
bool is_home_bay() {
    return (frog_y == MAX_Y && (frog_x % 4 < 2));
}

/**
 * @brief Validates whether Frogger is legally allowed to execute a move. 
 *        Prevents him from jumping off the edge of the world, into a filled bay, or while
 *        being transported by a log across the edge.
 * @param None
 * @return true if the intended move is legal, false if it is blocked by map constraints.
 */
bool can_jump() {
    // Prevent jumping when in the wrap zone
    if (frog_x > MAX_X) return false;

    // Prevent jumping when at the upper or lower map bounds
    if (frog_y >= MAX_Y || frog_y < 0) return false;

    // Prevent jumping into a bay that has already been filled
    if (frog_y == MAX_Y - 1) {
        if ((frog_x % 4 < 2) && bay_occupied[frog_x / 4] == true) return false;
    }
    return true;
}

